// Core classification and reporting logic for the secret-rotation validator.
//
// Everything here is pure and deterministic: callers inject "now" so the same
// inputs always produce the same output, which is essential for the exact-value
// assertions our tests (and the CI pipeline) make.

import type {
  RotationReport,
  Secret,
  SecretStatus,
  Urgency,
  ValidateOptions,
} from "./types";

/** Milliseconds in a single day, used for whole-day age math. */
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Stable ordering of urgency buckets, most -> least urgent. */
const URGENCY_ORDER: Record<Urgency, number> = {
  expired: 0,
  warning: 1,
  ok: 2,
};

/**
 * Whole days between two instants, floored. We floor (rather than round) so a
 * secret only "ages" a full day once a complete 24h period has elapsed.
 */
function wholeDaysBetween(from: Date, to: Date): number {
  return Math.floor((to.getTime() - from.getTime()) / MS_PER_DAY);
}

/**
 * Classify a single secret relative to `now` and a configurable warning window.
 *
 * - `daysUntilExpiry <= 0`  -> expired (due today or overdue)
 * - within the warning window -> warning
 * - otherwise -> ok
 */
export function classifySecret(
  secret: Secret,
  now: Date,
  warningWindowDays: number,
): SecretStatus {
  const lastRotated = new Date(secret.lastRotated);
  if (Number.isNaN(lastRotated.getTime())) {
    throw new Error(
      `Secret "${secret.name}" has an invalid lastRotated date: "${secret.lastRotated}"`,
    );
  }

  const daysSinceRotation = wholeDaysBetween(lastRotated, now);
  const daysUntilExpiry = secret.rotationPolicyDays - daysSinceRotation;

  let urgency: Urgency;
  if (daysUntilExpiry <= 0) {
    urgency = "expired";
  } else if (daysUntilExpiry <= warningWindowDays) {
    urgency = "warning";
  } else {
    urgency = "ok";
  }

  return { ...secret, daysSinceRotation, daysUntilExpiry, urgency };
}

/**
 * Validate a set of secrets, producing a full report: a flat list sorted
 * most-urgent-first, the same statuses grouped by urgency, and summary counts.
 */
export function validateSecrets(
  secrets: Secret[],
  options: ValidateOptions,
): RotationReport {
  const { now, warningWindowDays } = options;

  if (warningWindowDays < 0) {
    throw new Error(
      `warningWindowDays must be non-negative, received ${warningWindowDays}`,
    );
  }

  const statuses = secrets.map((s) =>
    classifySecret(s, now, warningWindowDays),
  );

  // Sort by urgency bucket first, then by days-until-expiry ascending so the
  // most overdue (most negative) secret bubbles to the top within a bucket.
  const sorted = [...statuses].sort((a, b) => {
    const byBucket = URGENCY_ORDER[a.urgency] - URGENCY_ORDER[b.urgency];
    if (byBucket !== 0) return byBucket;
    return a.daysUntilExpiry - b.daysUntilExpiry;
  });

  const byUrgency = {
    expired: sorted.filter((s) => s.urgency === "expired"),
    warning: sorted.filter((s) => s.urgency === "warning"),
    ok: sorted.filter((s) => s.urgency === "ok"),
  };

  return {
    generatedAt: now.toISOString(),
    warningWindowDays,
    summary: {
      total: sorted.length,
      expired: byUrgency.expired.length,
      warning: byUrgency.warning.length,
      ok: byUrgency.ok.length,
    },
    secrets: sorted,
    byUrgency,
  };
}

