// Command-line interface for the secret-rotation validator.
//
// `run()` is written to be testable: it takes argv plus an injectable file
// reader and returns a result object ({ stdout, stderr, exitCode }) instead of
// touching process state directly. The thin `main()` wrapper at the bottom
// wires it to the real filesystem and process exit code.
import { parseConfig } from "./config";
import { renderReport, type OutputFormat } from "./report";
import { validateSecrets } from "./validator";

/** Parsed and validated CLI options. */
export interface CliOptions {
  /** Path to the secret configuration JSON file. */
  input: string;
  /** Days-before-expiry threshold for the "warning" bucket. */
  warningWindowDays: number;
  /** Output format. */
  format: OutputFormat;
  /** Optional reference "now" (ISO date string); defaults to the real now. */
  now?: string;
  /** When true, exit non-zero if any secret is expired (CI gate). */
  failOnExpired: boolean;
}

/** Result of a CLI run, kept free of process side effects for testability. */
export interface RunResult {
  stdout: string;
  stderr: string;
  exitCode: number;
}

const VALID_FORMATS: readonly OutputFormat[] = ["markdown", "json"];

/**
 * Parse raw argv into validated {@link CliOptions}.
 * @throws on missing values or invalid flag arguments.
 */
export function parseArgs(argv: string[]): CliOptions {
  const opts: CliOptions = {
    input: "",
    warningWindowDays: 14,
    format: "markdown",
    failOnExpired: false,
  };

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i]!;
    switch (arg) {
      case "--input":
      case "-i":
        opts.input = requireValue(argv, ++i, arg);
        break;
      case "--warning":
      case "-w": {
        const raw = requireValue(argv, ++i, arg);
        const n = Number(raw);
        if (!Number.isFinite(n) || n < 0) {
          throw new Error(
            `Invalid --warning value "${raw}": must be a non-negative number`,
          );
        }
        opts.warningWindowDays = n;
        break;
      }
      case "--format":
      case "-f": {
        const raw = requireValue(argv, ++i, arg);
        if (!VALID_FORMATS.includes(raw as OutputFormat)) {
          throw new Error(
            `Invalid --format "${raw}": expected one of ${VALID_FORMATS.join(", ")}`,
          );
        }
        opts.format = raw as OutputFormat;
        break;
      }
      case "--now":
        opts.now = requireValue(argv, ++i, arg);
        break;
      case "--fail-on-expired":
        opts.failOnExpired = true;
        break;
      case "--help":
      case "-h":
        // Surface help via a sentinel the caller can detect if desired.
        throw new Error("HELP");
      default:
        throw new Error(`Unknown argument: "${arg}"`);
    }
  }

  return opts;
}

/** Read the next argv value or throw if the flag is missing its argument. */
function requireValue(argv: string[], index: number, flag: string): string {
  const value = argv[index];
  if (value === undefined) {
    throw new Error(`Flag "${flag}" requires a value`);
  }
  return value;
}

/**
 * Run the validator end to end.
 *
 * Exit codes:
 *   0 — success
 *   1 — `--fail-on-expired` set and at least one secret is expired
 *   2 — usage / parsing / I/O error (with a message on stderr)
 */
export function run(
  argv: string[],
  readFile: (path: string) => string,
): RunResult {
  let opts: CliOptions;
  try {
    opts = parseArgs(argv);
  } catch (err) {
    return fail(messageOf(err));
  }

  if (!opts.input) {
    return fail("Missing required --input <path> argument");
  }

  // Resolve the reference date up front so a bad --now is reported clearly.
  const now = opts.now ? new Date(opts.now) : new Date();
  if (Number.isNaN(now.getTime())) {
    return fail(`Invalid --now date: "${opts.now}"`);
  }

  let text: string;
  try {
    text = readFile(opts.input);
  } catch (err) {
    return fail(`Could not read input file "${opts.input}": ${messageOf(err)}`);
  }

  try {
    const secrets = parseConfig(text);
    const report = validateSecrets(secrets, {
      now,
      warningWindowDays: opts.warningWindowDays,
    });
    const stdout = renderReport(report, opts.format);
    const exitCode = opts.failOnExpired && report.summary.expired > 0 ? 1 : 0;
    return { stdout, stderr: "", exitCode };
  } catch (err) {
    return fail(messageOf(err));
  }
}

/** Build a failure result (exit code 2) with the message on stderr. */
function fail(message: string): RunResult {
  return { stdout: "", stderr: message, exitCode: 2 };
}

/** Extract a string message from an unknown thrown value. */
function messageOf(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

/** Real entry point: wire run() to the filesystem and process. */
function main(): void {
  const { readFileSync } = require("node:fs") as typeof import("node:fs");
  const res = run(process.argv.slice(2), (path) =>
    readFileSync(path, "utf8"),
  );
  if (res.stdout) process.stdout.write(res.stdout.endsWith("\n") ? res.stdout : res.stdout + "\n");
  if (res.stderr) process.stderr.write(`Error: ${res.stderr}\n`);
  process.exit(res.exitCode);
}

// Only run main() when executed directly (not when imported by tests).
if (import.meta.main) {
  main();
}

