import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { join } from "node:path";
// Bun parses YAML imports natively, giving us the real parsed structure.
import workflow from "../.github/workflows/secret-rotation-validator.yml";

const underAct = !!process.env.ACT;
const ROOT = join(import.meta.dir, "..");
const WORKFLOW_PATH = join(ROOT, ".github/workflows/secret-rotation-validator.yml");

// Collect every `run:` script across all jobs/steps for path-reference checks.
function allRunScripts(wf: any): string {
  return Object.values(wf.jobs)
    .flatMap((job: any) => job.steps ?? [])
    .map((step: any) => step.run ?? "")
    .join("\n");
}

